import (
	"container/heap"
	"fmt"
	"sort"
)

type Names []string

func (h Names) Len() int            { return len(h) }
func (h Names) Less(i, j int) bool  { return h[i] < h[j] }
func (h Names) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *Names) Push(v interface{}) { *h = append(*h, v.(string)) }
func (h *Names) Pop() interface{} {
	old := *h
	last := old[len(old)-1]
	*h = old[:len(old)-1]
	return last
}
func plan(deps map[string][]string) ([]string, []string) {
	degree := map[string]int{}
	next := map[string][]string{}
	for name, inputs := range deps {
		if _, ok := degree[name]; !ok {
			degree[name] = 0
		}
		for _, input := range inputs {
			degree[name]++
			if _, ok := degree[input]; !ok {
				degree[input] = 0
			}
			next[input] = append(next[input], name)
		}
	}
	ready := &Names{}
	heap.Init(ready)
	for name, n := range degree {
		if n == 0 {
			heap.Push(ready, name)
		}
	}
	order := []string{}
	for ready.Len() > 0 {
		name := heap.Pop(ready).(string)
		order = append(order, name)
		for _, dependent := range next[name] {
			degree[dependent]--
			if degree[dependent] == 0 {
				heap.Push(ready, dependent)
			}
		}
	}
	remaining := []string{}
	for name, n := range degree {
		if n > 0 {
			remaining = append(remaining, name)
		}
	}
	sort.Strings(remaining)
	return order, remaining
}
func main() {
	order, cycle := plan(map[string][]string{"parse": {}, "compile": {"parse"}, "test": {"compile"}, "link": {"compile"}})
	fmt.Printf("order=%v remaining=%v\n", order, cycle)
	_, cycle = plan(map[string][]string{"a": {"b"}, "b": {"a"}})
	fmt.Printf("cycle=%v\n", cycle)
}

package main

import (
	"container/heap"
	"fmt"
	"sort"
)

type Booking struct {
	ID         string
	Start, End int
}
type Room struct{ End, ID int }
type Active []Room

func (h Active) Len() int { return len(h) }
func (h Active) Less(i, j int) bool {
	if h[i].End != h[j].End {
		return h[i].End < h[j].End
	}
	return h[i].ID < h[j].ID
}
func (h Active) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *Active) Push(v interface{}) { *h = append(*h, v.(Room)) }
func (h *Active) Pop() interface{}   { old := *h; v := old[len(old)-1]; *h = old[:len(old)-1]; return v }
func main() {
	bookings := []Booking{{"A", 0, 30}, {"B", 5, 10}, {"C", 10, 20}, {"D", 30, 40}}
	sort.SliceStable(bookings, func(i, j int) bool { return bookings[i].Start < bookings[j].Start })
	active := &Active{}
	heap.Init(active)
	rooms := 0
	for _, booking := range bookings {
		if booking.Start >= booking.End {
			panic("bad interval")
		}
		room := 0
		if active.Len() > 0 && (*active)[0].End <= booking.Start {
			room = heap.Pop(active).(Room).ID
		} else {
			rooms++
			room = rooms
		}
		heap.Push(active, Room{booking.End, room})
		fmt.Printf("%s=room%d\n", booking.ID, room)
	}
	fmt.Printf("rooms=%d\n", rooms)
}

package main

import (
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"sort"
)

type Entry struct {
	Name   string `json:"name"`
	Size   int    `json:"size"`
	Digest string `json:"sha256"`
}

func digest(text string) string { sum := sha256.Sum256([]byte(text)); return fmt.Sprintf("%x", sum) }
func main() {
	manifest := []Entry{{"ok.txt", 2, digest("ok")}, {"changed.txt", 3, digest("old")}, {"missing.txt", 1, digest("x")}}
	wire, err := json.Marshal(manifest)
	if err != nil {
		panic(err)
	}
	var decoded []Entry
	if err = json.Unmarshal(wire, &decoded); err != nil {
		panic(err)
	}
	files := map[string]string{"ok.txt": "ok", "changed.txt": "NEW!"}
	issues := []string{}
	for _, item := range decoded {
		data, exists := files[item.Name]
		if !exists {
			issues = append(issues, item.Name+":missing")
			continue
		}
		if len(data) != item.Size {
			issues = append(issues, item.Name+":size")
		}
		if digest(data) != item.Digest {
			issues = append(issues, item.Name+":digest")
		}
	}
	sort.Strings(issues)
	for _, issue := range issues {
		fmt.Println(issue)
	}
	fmt.Printf("issues=%d\n", len(issues))
}

package main

import (
	"fmt"
	"sort"
	"strings"
)

type Order struct {
	Department, State string
	Cents             int
}
type Total struct{ Count, Cents int }

func main() {
	orders := []Order{{"North", "paid", 1200}, {"south", "paid", 900}, {"north", "draft", 300}, {"NORTH", "paid", 700}, {"south", "paid", 100}}
	groups := map[string]Total{}
	for _, order := range orders {
		if order.State != "paid" || order.Cents < 500 {
			continue
		}
		key := strings.ToLower(order.Department)
		total := groups[key]
		total.Count++
		total.Cents += order.Cents
		groups[key] = total
	}
	names := []string{}
	for name := range groups {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		total := groups[name]
		fmt.Printf("%s count=%d cents=%d\n", name, total.Count, total.Cents)
	}
}

package main

import (
	"encoding/json"
	"fmt"
)

type Event struct {
	Kind   string `json:"kind"`
	Amount int    `json:"amount"`
}
type State struct {
	Open    bool
	Balance int
}

func apply(state State, event Event) (State, error) {
	next := state
	switch event.Kind {
	case "open":
		if state.Open {
			return state, fmt.Errorf("already open")
		}
		next.Open = true
	case "credit", "debit":
		if !state.Open || event.Amount <= 0 {
			return state, fmt.Errorf("invalid amount/state")
		}
		if event.Kind == "credit" {
			next.Balance += event.Amount
		} else {
			if event.Amount > state.Balance {
				return state, fmt.Errorf("insufficient funds")
			}
			next.Balance -= event.Amount
		}
	default:
		return state, fmt.Errorf("unknown event")
	}
	return next, nil
}
func main() {
	var events []Event
	if err := json.Unmarshal([]byte(`[{"kind":"open"},{"kind":"credit","amount":100},{"kind":"debit","amount":30},{"kind":"debit","amount":90},{"kind":"other"}]`), &events); err != nil {
		panic(err)
	}
	state := State{}
	for index, event := range events {
		next, err := apply(state, event)
		if err != nil {
			fmt.Printf("event%d rejected balance=%d\n", index, state.Balance)
			continue
		}
		state = next
	}
	fmt.Printf("final=%d\n", state.Balance)
}

package main

import (
	"fmt"
)

type Change struct {
	Item  string
	Delta int
}

func transact(stock map[string]int, changes []Change) error {
	next := map[string]int{}
	for item, value := range stock {
		next[item] = value
	}
	for _, change := range changes {
		value, exists := next[change.Item]
		if !exists {
			return fmt.Errorf("unknown item")
		}
		value += change.Delta
		if value < 0 {
			return fmt.Errorf("negative stock")
		}
		next[change.Item] = value
	}
	for item, value := range next {
		stock[item] = value
	}
	return nil
}
func main() {
	stock := map[string]int{"pen": 10, "pad": 4}
	err := transact(stock, []Change{{"pen", -3}, {"pad", -9}})
	fmt.Printf("failed=%t pen=%d pad=%d\n", err != nil, stock["pen"], stock["pad"])
	err = transact(stock, []Change{{"pen", -3}, {"pad", 2}})
	fmt.Printf("committed=%t pen=%d pad=%d\n", err == nil, stock["pen"], stock["pad"])
}

